refentry.refsect1:
&reftitle.description;
DOMAttrDOMElementdom_import_simplexml objectnode
Questa funzione prende il nodo attributo o elemento node fornito (un'istanza di SimpleXMLElement) e crea rispettivamente un nodo DOMAttr o DOMElement. Il nuovo DOMNode fa riferimento allo stesso nodo XML sottostante del SimpleXMLElement.

&reftitle.parameters;




   node



     Il nodo attributo o elemento da importare (un'istanza di SimpleXMLElement).

&reftitle.changelog;





    &Version;
    &Description;





    8.0.0

     Questa funzione non restituisce più &null; in caso di fallimento.

  &reftitle.examples;

   Importare SimpleXML nel DOM con dom_import_simplexml


<?php

$sxe = simplexml_load_string('<books><book><title>blah</title></book></books>');

if ($sxe === false) {
    echo 'Errore durante il parsing del documento';
    exit;
}

$dom_sxe = dom_import_simplexml($sxe);
if (!$dom_sxe) {
    echo 'Errore durante la conversione dell\'XML';
    exit;
}

$dom = new DOMDocument('1.0');
$dom_sxe = $dom->importNode($dom_sxe, true);
$dom_sxe = $dom->appendChild($dom_sxe);

echo $dom->saveXML();

?>


   &example.outputs;


<?xml version="1.0"?>
<books><book><title>blah</title></book></books>




   Importare SimpleXML nel DOM e modificare SimpleXML tramite il DOM

    La gestione degli errori è omessa per brevità.



<?php

$sxe = simplexml_load_string('<books><book><title>blah</title></book></books>');
$elt = dom_import_simplexml($sxe);
$elt->setAttribute("foo", "bar");
echo $sxe->asXML();

?>


   &example.outputs;


<?xml version="1.0"?>
<books foo="bar"><book><title>blah</title></book></books>
